static void addToClassPath(Vector<URL> cpV, String dir) throws Exception {
    // Ignore the file path if it is not a directory
    if (!new File(dir).isDirectory()) {
        return;
    }

    // Get all the jar files in the directory
    File[] jarFiles = new File(dir).listFiles((file) -> {
        return file.getName().endsWith(".jar");
    });

    // Iterate over all the jar files and add them to the classpath
    for (File jarFile : jarFiles) {
        cpV.add(jarFile.toURI().toURL());
