	Graph<V, E> newGraph = new Graph<>();
	newGraph.setAllowParallelEdges(target.getAllowParallelEdges());
	newGraph.setAutoRemoveEdges(target.getAutoRemoveEdges());
	newGraph.setDefaultEdgeWeight(target.getDefaultEdgeWeight());
	newGraph.setDefaultNodeWeight(target.getDefaultNodeWeight());
	newGraph.setEdgeLabelComparator(target.getEdgeLabelComparator());
	newGraph.setEdgeWeightComparator(target.getEdgeWeightComparator());
	newGraph.setNodeComparator(target.getNodeComparator());
	newGraph.setNodeLabelComparator(target.getNodeLabelComparator());
	newGraph.setNodeWeightComparator(target.getNodeWeightComparator());

	// Set the graph type
	newGraph.setType(target.getType());

	// Add nodes from the target graph to the new graph
	for (V node : target.getNodes()) {
		newGraph.addNode(node);
	}

	// Add edges from the target graph to the new graph
	for (E edge : target.getEdges()) {
		newGraph.addEdge(edge);
	}

	// Set the result map with the nodes and edges from the new graph
	resultMap.put("nodes", newGraph.getNodes());
	resultMap.put("edges", newGraph.getEdges());
}

