public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {

    List<ThreadSnapshot> snapshots = new ArrayList<>();
    try (RandomAccessFile raf = new RandomAccessFile(file, "r")) {
        raf.seek(0);
        String line;
        while ((line = raf.readLine()) != null) {
            if (line.startsWith("#")) {
                continue;
            }
            String[] values = line.split(",");
            if (values.length != 6) {
                throw new IOException("Invalid line: " + line);
            }
            String timestamp = values[0];
            long start = Long.parseLong(values[2]);
            long end = Long.parseLong(values[3]);
            boolean isACoreThread = Boolean.parseBoolean(values[4]);
            String threadName = values[5];
            ProfileAnalyzeTimeRange targetRange = null;
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (range.getStart() <= start && range.getEnd() >= end) {
                    targetRange = range;
                    break;
                }
            }
            if (targetRange == null) {
                continue;
            }
            ThreadSnapshot snapshot = new ThreadSnapshot(start, end, isACoreThread, threadName);
            snapshots.add(snapshot);
        }
    } catch (IOException e) {
        throw new IOException("Error parsing file: " + file.getName(), e);
    }
    return snapshots;
}

